<script setup lang="ts">
import{computed,onMounted,reactive,ref,watch}from'vue';import type{ColDef}from'ag-grid-community';import{ElMessage,ElMessageBox}from'element-plus';import AppDataGrid from'@/components/AppDataGrid.vue';import{deleteDeployConfig,executeDeploy,getDeployConfig,listCertificates,listDeployConfigs,saveDeployConfig,testDeployConfig,type SSLCertificate,type SSLDeployConfig}from'@/api/ssl-cert';import{useAuthStore}from'@/stores/auth'
const auth=useAuthStore(),rows=ref<SSLDeployConfig[]>([]),certs=ref<SSLCertificate[]>([]),keyword=ref(''),certID=ref(0),deployType=ref(''),page=ref(1),pageSize=ref(20),total=ref(0),loading=ref(false),dialog=ref(false);const empty=()=>({id:undefined as number|undefined,certificate_id:0,name:'',deploy_type:'nginx_ssh',target_config:'{}',auto_deploy:true,enabled:true});const form=reactive(empty())
async function load(){loading.value=true;try{const{data}=await listDeployConfigs({keyword:keyword.value,certificate_id:certID.value,deploy_type:deployType.value,page:page.value,limit:pageSize.value});rows.value=data.data.list;total.value=data.data.total}finally{loading.value=false}}async function open(row?:SSLDeployConfig){Object.assign(form,empty());if(row){const{data}=await getDeployConfig(row.id);Object.assign(form,data.data)}dialog.value=true}async function save(){if(!form.name.trim()||!form.certificate_id)return ElMessage.warning('请填写配置名称并选择证书');await saveDeployConfig(form);dialog.value=false;ElMessage.success('保存成功');await load()}async function remove(row:SSLDeployConfig,confirm=true){if(confirm)await ElMessageBox.confirm(`确认删除“${row.name}”吗？`,'删除确认',{type:'warning'});await deleteDeployConfig(row.id)}async function bulkDelete(items:unknown[]){await ElMessageBox.confirm(`确认删除选中的 ${items.length} 项吗？`,'批量删除',{type:'warning'});for(const row of items as SSLDeployConfig[])await remove(row,false);await load()}async function test(row:SSLDeployConfig){await testDeployConfig(row.id);ElMessage.success('部署配置验证通过')}async function execute(row:SSLDeployConfig){await executeDeploy(row.id);ElMessage.success('部署任务已创建')}
function actions(p:{data:SSLDeployConfig}){const w=document.createElement('div');w.className='ssl-actions';const add=(t:string,c:string,f:()=>void)=>{const b=document.createElement('button');b.textContent=t;b.className=c;b.onclick=f;w.append(b)};if(auth.hasPermission('POST /api/v1/ssl-cert/deploy-configs/execute'))add('部署','ssl-test',()=>void execute(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/deploy-configs/test'))add('测试','ssl-link',()=>void test(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/deploy-configs/save'))add('编辑','ssl-edit',()=>void open(p.data));if(auth.hasPermission('POST /api/v1/ssl-cert/deploy-configs/delete'))add('删除','ssl-delete',()=>void remove(p.data).then(load));return w}
const columns=computed<ColDef[]>(()=>[{headerName:'序号',width:64,valueGetter:p=>(page.value-1)*pageSize.value+(p.node?.rowIndex||0)+1},{field:'name',headerName:'配置名称',minWidth:140},{field:'certificate_name',headerName:'证书',minWidth:140},{field:'deploy_type',headerName:'部署类型',width:110,valueFormatter:p=>p.value==='k8s_secret'?'K8s Secret':'Nginx SSH'},{field:'auto_deploy',headerName:'自动部署',width:90,valueFormatter:p=>p.value?'是':'否'},{field:'enabled',headerName:'状态',width:80,valueFormatter:p=>p.value?'启用':'停用'},{field:'last_deploy_ok',headerName:'最近部署',width:95,valueFormatter:p=>p.data.last_deploy_at?(p.value?'成功':'失败'):'未部署'},{headerName:'操作',pinned:'right',width:250,cellRenderer:actions}]);watch([keyword,certID,deployType],()=>{page.value=1;void load()});onMounted(async()=>{await load();const{data}=await listCertificates({keyword:'',status:'',source_type:'',page:1,limit:1000});certs.value=data.data.list})
</script>
<template><section class="ssl-page"><header><h2>部署配置</h2><p>配置证书到 Nginx 主机或 Kubernetes Secret 的部署目标。</p></header><div class="toolbar"><div class="filters"><el-input v-model="keyword" placeholder="搜索配置名称" clearable/><el-select v-model="certID" placeholder="选择证书" clearable><el-option v-for="item in certs" :key="item.id" :label="`${item.name}（${item.domain}）`" :value="item.id"/></el-select><el-select v-model="deployType" placeholder="选择部署类型" clearable><el-option label="Nginx SSH" value="nginx_ssh"/><el-option label="K8s Secret" value="k8s_secret"/></el-select></div><el-button v-permission="'POST /api/v1/ssl-cert/deploy-configs/save'" type="primary" @click="open()">新增部署配置</el-button></div><AppDataGrid v-loading="loading" class="grid" :row-data="rows" :column-defs="columns" pagination server-pagination :total="total" :current-page="page" :page-size="pageSize" :bulk-delete="auth.hasPermission('POST /api/v1/ssl-cert/deploy-configs/delete')?bulkDelete:undefined" @page-change="v=>{page=v;void load()}" @page-size-change="v=>{pageSize=v;page=1;void load()}"/><el-dialog v-model="dialog" :title="form.id?'编辑部署配置':'新增部署配置'" width="650px"><el-form label-width="90px"><el-form-item label="配置名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="关联证书" required><el-select v-model="form.certificate_id" style="width:100%"><el-option v-for="item in certs" :key="item.id" :label="`${item.name}（${item.domain}）`" :value="item.id"/></el-select></el-form-item><el-form-item label="部署类型" required><el-select v-model="form.deploy_type" style="width:100%"><el-option label="Nginx SSH" value="nginx_ssh"/><el-option label="Kubernetes Secret" value="k8s_secret"/></el-select></el-form-item><el-form-item label="目标配置" required><el-input v-model="form.target_config" type="textarea" :rows="9" placeholder="请输入部署目标 JSON"/></el-form-item><div class="switches"><el-form-item label="自动部署"><el-switch v-model="form.auto_deploy"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<style scoped>.ssl-page{height:100%;display:flex;flex-direction:column;gap:8px;min-width:0;padding:0 4px;font-size:11px}header h2{margin:0;font-size:20px}header p{margin:3px 0 0;color:var(--text-soft)}.toolbar{display:flex;justify-content:space-between;gap:8px}.filters{display:flex;gap:6px}.filters .el-input{width:150px}.filters .el-select{width:150px}.grid{flex:1;min-height:0}.switches{display:grid;grid-template-columns:1fr 1fr}:deep(.ssl-actions){height:100%;display:flex;align-items:center;gap:4px}:deep(.ssl-actions button){height:26px;border-radius:8px;padding:3px 7px;background:#fff;cursor:pointer}:deep(.ssl-edit){border:1px solid var(--primary);color:var(--primary)}:deep(.ssl-test),:deep(.ssl-link){border:1px solid #7bcf91;color:#27ae60}:deep(.ssl-delete){border:1px solid #f3b4b4;color:var(--danger)}</style>
